PROGRAM MotorStarterLatch
  VAR_INPUT
    StartPB : BOOL := FALSE;
    StopPB : BOOL := TRUE;
    OverloadTrip : BOOL := FALSE;
  END_VAR
  VAR_OUTPUT
    MotorContactor : BOOL := FALSE;
    FaultLamp : BOOL := FALSE;
  END_VAR

  MotorContactor := (StartPB OR MotorContactor) AND StopPB AND NOT OverloadTrip;
  FaultLamp := OverloadTrip;
END_PROGRAM

(* Conveyor Batch Counter with Pneumatic Diverter Actuation *)
PROGRAM ConveyorBatchControl
  VAR_INPUT
    ConveyorEnable : BOOL;
    PhotoEyeSensor : BOOL;
    ManualReset : BOOL;
    BatchTarget : INT := 12;
  END_VAR
  VAR_OUTPUT
    BeltDriveRun : BOOL := FALSE;
    DiverterValve : BOOL := FALSE;
    BatchReadyLamp : BOOL := FALSE;
    PartsCounted : INT := 0;
  END_VAR
  VAR
    PartEdge : R_TRIG;
    BatchCounter : CTU;
    DiverterTimer : TON;
    PartPulse : BOOL := FALSE;
    BatchReached : BOOL := FALSE;
    DiverterDone : BOOL := FALSE;
    AutoResetPulse : BOOL := FALSE;
  END_VAR

  BeltDriveRun := ConveyorEnable;

  (* Rising-edge detection on optical part sensor *)
  PartEdge(CLK := PhotoEyeSensor AND BeltDriveRun, Q => PartPulse);

  (* Count parts up to BatchTarget *)
  AutoResetPulse := ManualReset OR DiverterDone;
  BatchCounter(
    CU := PartPulse,
    R := AutoResetPulse,
    PV := BatchTarget,
    Q => BatchReached,
    CV => PartsCounted
  );

  (* Hold pneumatic diverter extended for 2.5 seconds once batch is full *)
  DiverterTimer(IN := BatchReached, PT := T#2500ms, Q => DiverterDone);

  DiverterValve := BatchReached AND NOT DiverterDone;
  BatchReadyLamp := BatchReached;
END_PROGRAM

PROGRAM TankLevelControl
  VAR_INPUT
    LevelPV : REAL := 50.0;
    LevelSP : REAL := 60.0;
    HighLevelSwitch : BOOL := FALSE;
  END_VAR
  VAR_OUTPUT
    Pump1SpeedPct : REAL := 0.0;
    Pump2BoostRun : BOOL := FALSE;
    HighLevelAlarm : BOOL := FALSE;
  END_VAR
  VAR
    Error : REAL := 0.0;
    IntegralTerm : REAL := 0.0;
    Kp : REAL := 2.2;
    Ki : REAL := 0.15;
    Dt : REAL := 0.1;
    RawCmd : REAL := 0.0;
  END_VAR

  Error := LevelSP - LevelPV;
  IntegralTerm := IntegralTerm + (Ki * Error * Dt);

  IF IntegralTerm > 80.0 THEN
    IntegralTerm := 80.0;
  ELSIF IntegralTerm < 0.0 THEN
    IntegralTerm := 0.0;
  END_IF;

  RawCmd := (Kp * Error) + IntegralTerm;
  IF RawCmd > 100.0 THEN
    Pump1SpeedPct := 100.0;
  ELSIF RawCmd < 0.0 THEN
    Pump1SpeedPct := 0.0;
  ELSE
    Pump1SpeedPct := RawCmd;
  END_IF;

  Pump2BoostRun := (Pump1SpeedPct > 85.0) AND NOT HighLevelSwitch;
  HighLevelAlarm := HighLevelSwitch;
END_PROGRAM

PROGRAM PackagingLineMain
  VAR_INPUT
    EStopHealthy : BOOL := TRUE;
    GuardClosed : BOOL := TRUE;
    StartCmd : BOOL := FALSE;
    StopCmd : BOOL := FALSE;
    CartonReady : BOOL := FALSE;
  END_VAR
  VAR_OUTPUT
    StateCode : INT := 0;
    SealHeaterOn : BOOL := FALSE;
    DriveEnable : BOOL := FALSE;
  END_VAR
  VAR
    SafetyOk : BOOL := FALSE;
    WarmupDone : BOOL := FALSE;
    WarmupTimer : TON;
  END_VAR

  SafetyOk := EStopHealthy AND GuardClosed;

  IF NOT SafetyOk THEN
    StateCode := 99;
    DriveEnable := FALSE;
    SealHeaterOn := FALSE;
  ELSE
    CASE StateCode OF
      0:
        DriveEnable := FALSE;
        IF StartCmd THEN
          StateCode := 10;
        END_IF;
      10:
        SealHeaterOn := TRUE;
        WarmupTimer(IN := TRUE, PT := T#5s, Q => WarmupDone);
        IF WarmupDone THEN
          StateCode := 20;
        END_IF;
      20:
        DriveEnable := CartonReady;
        IF StopCmd THEN
          StateCode := 0;
        END_IF;
      99:
        IF NOT StartCmd THEN
          StateCode := 0;
        END_IF;
    END_CASE;
  END_IF;
END_PROGRAM

